-- Sample data for the Job Scheduler: 120 scheduled jobs, 150 executions and 230 attempts.
--
-- The three tables interlock, so this data is generated rather than hand-written: an
-- execution's job_snapshot agrees with the job it came from, its next_occurrence_at is the
-- cron occurrence following its scheduled_for, and its attempts tell a story consistent with
-- its status and attempt_count. Hand-maintaining 400+ such rows would guarantee drift.
--
-- Two invariants of the retry engine are deliberately upheld here, because seed data that
-- contradicted them would teach the wrong rule to anyone reading the table:
--
--   * There is NO attempt row for a retry that was cancelled before it started. A cancelled
--     candidate is not an attempt; the execution records it as RETRY_WINDOW_EXPIRED instead.
--   * No next_retry_at falls on or after its execution's next_occurrence_at. A retry that
--     reached the following occurrence is exactly the one the engine refuses to schedule.
--
-- Ids are synthetic and deterministic ('01M2JBJ...' jobs, '01M2JBE...' executions,
-- '01M2JBA...' attempts) so the migration produces identical rows on every machine and is
-- visibly seed data rather than something a user created. Timestamps derive from one fixed
-- epoch in the past, so these read as history and the scheduler does not wake up on boot
-- believing it has 150 occurrences to catch up on.

DO $$
BEGIN
	IF EXISTS (
		SELECT FROM information_schema.tables
		WHERE table_schema = 'public' AND table_name = 'jobscheduler_jobs'
	) THEN
		INSERT INTO "jobscheduler_jobs" (
			"id", "name", "job_type", "module_name", "job_key", "action_type", "action_config",
			"cron_expression", "effective_from", "effective_until", "is_enabled", "max_attempts",
			"retry_interval_seconds", "concurrency_policy", "misfire_policy", "next_run_at",
			"created_at", "etag"
		) VALUES
